const D = { scale:1, n:8, energy:.6, hue:205, speed:1, density:.4, gap:.5, chub:.5, trip:.5, x:.5, y:.72, seed:0, style:'poster', act:'march' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };
const TAU = 6.28318530718, PI = Math.PI;
const u = Math.min(width, height);
const N = Math.max(1, Math.round(P.n));
let bt = K.beat * P.speed;
if (S.lastBeat == null || bt < S.lastBeat) S.lastBeat = bt;
S.lastBeat = bt;
S.rms = (S.rms||0)*.85 + (A.rms||0)*.15;
S.bass = (S.bass||0)*.8 + (A.bass||0)*.2;
S.tre = (S.tre||0)*.8 + (A.treble||0)*.2;

const H = ((P.hue%360)+360)%360;
const eAmp = (.4 + .6*P.energy) * (.6 + .5*K.intensity);
const kick = Math.min(1, K.pulse*(.5 + .5*K.intensity) + S.bass*.7);
const chub = P.chub;

const styles = ['poster','riso','silhouette','blueprint','noir'];
const st = styles.indexOf(P.style) >= 0 ? P.style : 'poster';
const wire = st === 'blueprint';
const sil = st === 'silhouette';

// ---- act dramaturgy: modulate march + trips ----
const ACT = P.act;
let marchRate, tripBias;
if (ACT === 'promenade') { marchRate = .016*P.speed*(.5+K.intensity); tripBias = P.trip*.5; }
else if (ACT === 'scramble') { marchRate = .042*P.speed*(.7+K.intensity); tripBias = P.trip*1.5; }
else { marchRate = .026*P.speed*(.55+.6*K.intensity); tripBias = P.trip; }
const globalScroll = bt*marchRate + K.t*P.speed*.012;

const tripIndex = Math.floor(fr(3)*N);
const M = u*0.16;
const spanW = width + 2*M;

// ---- ground ice strip (cached, translucent, lower band only) ----
if (!wire) {
  const gy = P.y*height;
  noStroke();
  const band = st==='noir' ? [H,18,16] : sil ? [H,26,13] : st==='riso' ? [195,26,80,60] : [198,20,70,55];
  fill(band[0], band[1], band[2], band[3]!=null?band[3]:40);
  rect(0, gy+u*0.03, width, height-(gy+u*0.03));
}

// ---- build penguin list with seeded depth ----
const list = [];
for (let i=0;i<N;i++){
  const off = i/N;
  let ph = (off + globalScroll) % 1; if (ph<0) ph+=1;
  const dep = .72 + .5*fr(i+5);
  const px = -M + ph*spanW;
  const hgt = u*0.24*P.scale*dep;
  const py = P.y*height + (dep-1)*u*0.055;
  list.push({i,off,px,py,hgt,dep});
}
list.sort((a,b)=>a.dep-b.dep);

function paint(role){
  noStroke();
  if (wire){
    noFill();
    stroke(role==='beak'||role==='foot'?32:195, 62, 96, 88);
    strokeWeight(Math.max(1, u*0.0016));
    return;
  }
  if (sil){ fill(H, 34, 10); return; }
  if (st==='noir'){
    if (role==='back') fill(H,26,15);
    else if (role==='belly') fill(H,10,34);
    else if (role==='beak'||role==='foot') fill(28,58,44);
    else if (role==='eye') fill(0,0,4);
    else if (role==='eyeW') fill(0,0,60);
    else fill(H,24,17);
    return;
  }
  if (st==='riso'){
    if (role==='back') fill(H,62,44,92);
    else if (role==='belly') fill(44,18,96,92);
    else if (role==='beak'||role==='foot') fill(18,86,95,92);
    else if (role==='eye') fill(H,60,22,95);
    else if (role==='eyeW') fill(0,0,100,90);
    else fill(H,56,46,92);
    return;
  }
  // poster
  if (role==='back') fill(H,50,26);
  else if (role==='belly') fill(45,10,97);
  else if (role==='beak'||role==='foot') fill(28,90,97);
  else if (role==='eye') fill(0,0,8);
  else if (role==='eyeW') fill(0,0,100);
  else fill(H,48,28);
}

for (let k=0;k<list.length;k++){
  const a = list[k];
  const hgt = a.hgt;
  const bw = hgt*(0.42 + chub*0.18);
  const phB = bt + a.off*4 + fr(a.i+9)*2;
  const sbp = ((phB%1)+1)%1;
  const swing = Math.sin(sbp*PI);
  const side = (Math.floor(phB)%2===0)?1:-1;

  // trip envelope (seeded, one penguin)
  let trip = 0;
  if (a.i === tripIndex && tripBias > 0){
    const period = 5;
    const c = Math.floor(bt/period);
    if (fr(c*13 + a.i*7 + 1) < tripBias*0.55){
      const loc = bt/period - c;
      if (loc < 0.22) trip = Math.sin(loc/0.22*PI);
    }
  }

  const sway = side*swing*hgt*0.05*(0.7+eAmp) + trip*hgt*0.05;
  const dyBob = -Math.abs(Math.sin(phB*PI))*hgt*0.05 - kick*hgt*0.03*eAmp + trip*hgt*0.06;
  const tilt = side*swing*0.11*(0.6+0.5*eAmp) + trip*0.5;
  const footL = side<0 ? swing : 0;
  const footR = side>0 ? swing : 0;
  const fSw = Math.sin(phB*PI)*0.28*(0.5+eAmp) + trip*1.5;
  const beak = (fr(Math.floor(phB)+a.i*3+30) < 0.3 ? kick*0.5 : 0) + trip*0.6;

  const cx = a.px + sway;
  const cy = a.py + dyBob;

  // ground shadow (screenprint sits it on ice)
  if (!wire){
    noStroke(); fill(0,0,0, sil?26:18);
    ellipse(a.px + sway*0.4, a.py + hgt*0.03, bw*1.7 - Math.abs(sway)*0.4, hgt*0.07);
  }

  push();
  translate(cx, cy);
  rotate(tilt);

  // poster hard drop-ink silhouette (screenprint offset)
  if (st==='poster'){
    noStroke(); fill(H,55,13);
    ellipse(hgt*0.03, -hgt*0.5 + hgt*0.02, bw*1.02, hgt*0.88);
  }

  // feet
  paint('foot');
  const fy = -hgt*0.015;
  push(); translate(-bw*0.26, fy - footL*hgt*0.11); rotate(-.04);
    if (wire) ellipse(0,0,bw*0.5,hgt*0.05);
    else { triangle(-bw*0.22,hgt*0.03,bw*0.22,hgt*0.03,0,-hgt*0.02); ellipse(0,hgt*0.03,bw*0.5,hgt*0.035); }
  pop();
  push(); translate(bw*0.26, fy - footR*hgt*0.11); rotate(.04);
    if (wire) ellipse(0,0,bw*0.5,hgt*0.05);
    else { triangle(-bw*0.22,hgt*0.03,bw*0.22,hgt*0.03,0,-hgt*0.02); ellipse(0,hgt*0.03,bw*0.5,hgt*0.035); }
  pop();

  // far flipper
  paint('back');
  push(); translate(-bw*0.46, -hgt*0.52); rotate(-0.25 - fSw);
    ellipse(0, hgt*0.12, bw*0.24, hgt*0.34);
  pop();

  // body mass
  paint('back');
  ellipse(0, -hgt*0.5, bw, hgt*0.88);
  if (wire){
    paint('back'); // stroke set
    line(0,-hgt*0.92,0,-hgt*0.08);
    ellipse(0,-hgt*0.5,bw*0.66,hgt*0.62);
    ellipse(0,-hgt*0.5,bw*0.4,hgt*0.42);
  }

  // belly
  if (!sil){
    paint('belly');
    ellipse(0, -hgt*0.42, bw*0.62, hgt*0.6);
    if (st==='riso'){ noStroke(); fill((H+28)%360,66,90,24); ellipse(-hgt*0.02,-hgt*0.5,bw,hgt*0.88); }
    if (st==='noir'){ noStroke(); fill(H,6,44,40); ellipse(-bw*0.18,-hgt*0.52,bw*0.5,hgt*0.7); }
  }

  // near flipper
  paint('back');
  push(); translate(bw*0.46, -hgt*0.52); rotate(0.25 + fSw);
    ellipse(0, hgt*0.12, bw*0.24, hgt*0.34);
  pop();

  // head region
  push();
  translate(0, -hgt*0.8 + Math.sin(phB*TAU)*hgt*0.01*eAmp);
  rotate(side*swing*0.05);
  // beak
  paint('beak');
  const bo = beak*hgt*0.05;
  if (wire){
    triangle(-bw*0.05,-bo*0.4, bw*0.05,-bo*0.4, 0,-hgt*0.09);
    triangle(-bw*0.06,bo, bw*0.06,bo, 0,hgt*0.07+bo);
  } else {
    triangle(-bw*0.07,-bo*0.4, bw*0.07,-bo*0.4, 0,-hgt*0.1);
    triangle(-bw*0.08,bo, bw*0.08,bo, 0,hgt*0.08+bo);
  }
  // eyes
  if (!sil){
    const ex = bw*0.2;
    const blink = ((K.t*0.3 + fr(a.i+11))%1) < 0.05;
    if (blink && !wire){
      paint('eye'); stroke(0,0,st==='noir'?4:8); strokeWeight(Math.max(1,hgt*0.008)); noFill();
      line(-ex-hgt*0.02,-hgt*0.12,-ex+hgt*0.02,-hgt*0.12);
      line(ex-hgt*0.02,-hgt*0.12,ex+hgt*0.02,-hgt*0.12);
      noStroke();
    } else {
      paint('eyeW'); ellipse(-ex,-hgt*0.12,bw*0.16,hgt*0.075); ellipse(ex,-hgt*0.12,bw*0.16,hgt*0.075);
      paint('eye'); ellipse(-ex,-hgt*0.12,bw*0.09,hgt*0.045); ellipse(ex,-hgt*0.12,bw*0.09,hgt*0.045);
    }
  }
  pop();

  pop();
}

// ---- ambient snow motes (density) ----
if (P.density > 0.02 && !wire){
  const n = Math.round(P.density*26);
  noStroke();
  for (let i=0;i<n;i++){
    const drift = (K.t*(0.1+fr(i+50)*0.16) + fr(i+70)) % 1;
    const fx = ((fr(i+90) + globalScroll*0.3)%1)*width;
    const fyv = ((drift + fr(i+110))%1)*u*0.85 + (P.y*height - u*0.6);
    const tw = 0.5 + 0.5*Math.sin(K.t*3 + i);
    fill(sil?H:50, sil?24:8, 100, (12+20*tw)*(0.4+0.6*P.density));
    ellipse(fx, fyv, (u*0.004)*(0.8+tw) + S.tre*u*0.006, (u*0.004)*(0.8+tw));
  }
}
